class TxnManagerShutdownTest {

	@ParameterizedTest
	@CsvSource({ "RESET,false", "RESET,true", "ABORT,false", "ABORT,true" })
	void concurrentReaderCloseDoesNotDeadlockShutdown(TxnManager.Mode mode, boolean untracked,
			@TempDir Path dataDir) throws Exception {
		// A monitor deadlock cannot be interrupted safely. Isolate the native environment and
		// threads in a child JVM so the failing case cannot leave the test runner deadlocked.
		Process process = new ProcessBuilder(
				Path.of(System.getProperty("java.home"), "bin", "java").toString(),
				"--enable-native-access=ALL-UNNAMED", "-cp", System.getProperty("java.class.path"),
				ShutdownProbe.class.getName(), dataDir.toString(), mode.name(), Boolean.toString(untracked))
						.redirectErrorStream(true)
						.start();
		try {
			assertTrue(process.waitFor(30, TimeUnit.SECONDS), "Concurrent shutdown probe did not finish");
			String output = new String(process.getInputStream().readAllBytes(), StandardCharsets.UTF_8);
			assertEquals(0, process.exitValue(), output);
		} finally {
			if (process.isAlive()) {
				process.destroyForcibly().waitFor();
			}
		}
	}

	public static final class ShutdownProbe {

		public static void main(String[] args) throws Exception {
			long env;
			try (MemoryStack stack = stackPush()) {
				PointerBuffer pointer = stack.mallocPointer(1);
				E(mdb_env_create(pointer));
				env = pointer.get(0);
				E(mdb_env_set_maxreaders(env, 4));
				E(mdb_env_open(env, args[0], MDB_NOTLS | MDB_NOSYNC | MDB_NOMETASYNC, 0664));
			}
			TxnManager manager = new TxnManager(env, TxnManager.Mode.valueOf(args[1]));
			TxnManager.Txn reader = Boolean.parseBoolean(args[2])
					? manager.createReadTxnUntracked()
					: manager.createReadTxn();
			// Leave a separate pooled reader to check that shutdown still releases every slot.
			manager.createReadTxn().close();
			CountDownLatch readerEntered = new CountDownLatch(1);
			CountDownLatch closeReader = new CountDownLatch(1);
			CountDownLatch finished = new CountDownLatch(2);
			AtomicReference<Throwable> failure = new AtomicReference<>();
			Thread readerThread = Thread.ofPlatform().daemon().name("reader-close").unstarted(() -> {
				try {
					synchronized (reader) {
						readerEntered.countDown();
						closeReader.await();
						reader.close();
					}
				} catch (Throwable error) {
					failure.compareAndSet(null, error);
				} finally {
					finished.countDown();
				}
			});
			Thread shutdownThread = Thread.ofPlatform().daemon().name("manager-close").unstarted(() -> {
				try {
					manager.close();
				} catch (Throwable error) {
					failure.compareAndSet(null, error);
				} finally {
					finished.countDown();
				}
			});
			readerThread.start();
			assertTrue(readerEntered.await(10, TimeUnit.SECONDS), "Reader did not enter its close monitor");
			shutdownThread.start();
			ThreadMXBean threads = ManagementFactory.getThreadMXBean();
			long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
			while (true) {
				ThreadInfo shutdown = threads.getThreadInfo(shutdownThread.threadId());
				if (shutdown != null && shutdown.getThreadState() == Thread.State.BLOCKED
						&& shutdown.getLockOwnerId() == readerThread.threadId()) {
					break;
				}
				assertTrue(System.nanoTime() < deadline, "Shutdown did not reach the reader close");
				Thread.onSpinWait();
			}
			closeReader.countDown();
			while (!finished.await(10, TimeUnit.MILLISECONDS)) {
				long[] deadlocked = threads.findMonitorDeadlockedThreads();
				if (deadlocked != null) {
					throw new AssertionError("Reader close and manager shutdown deadlocked:\n"
							+ threads.getThreadInfo(readerThread.threadId())
							+ threads.getThreadInfo(shutdownThread.threadId()));
				}
				assertTrue(System.nanoTime() < deadline, "Concurrent close did not finish");
			}
			if (failure.get() != null) {
				throw new AssertionError("Concurrent close failed", failure.get());
			}
			assertEquals(0, reader.get(), "Shutdown must release the reader handle");
			manager.close();
			long[] readers = new long[4];
			try (MemoryStack stack = stackPush()) {
				PointerBuffer pointer = stack.mallocPointer(1);
				for (int i = 0; i < readers.length; i++) {
					E(mdb_txn_begin(env, NULL, MDB_RDONLY, pointer));
					readers[i] = pointer.get(0);
				}
			} finally {
				for (long handle : readers) {
					if (handle != 0) {
						mdb_txn_abort(handle);
					}
				}
			}
			mdb_env_close(env);
		}
	}
}
